solution.code:
function firstIndex(a, target) {
  var low = 0;
  var high = a.length - 1;
  var answer = -1;
  while (low <= high) {
    var mid = Math.floor((low + high) / 2);
    if (a[mid] === target) {
      answer = mid;
      high = mid - 1;
    } else if (a[mid] < target) {
      low = mid + 1;
    } else {
      high = mid - 1;
    }
  }
  return answer;
}

console.log(firstIndex([1, 2, 2, 2, 3, 5], 2));
